// Totals per metric for this week vs last week, with % change. Replaces a 3-hour manual Excel job.
const rows = $input.all().map(i => i.json).filter(r => r && r.metric);
const today = $now.startOf('day');
const thisStart = today.minus({ days: 7 }).toISODate();
const sums = {};
for (const r of rows) {
  const bucket = r.day >= thisStart ? 'now' : 'prev';
  sums[r.metric] = sums[r.metric] || { now: 0, prev: 0 };
  sums[r.metric][bucket] += Number(r.value) || 0;
}
const fmt = n => n.toLocaleString('en-ZA', { maximumFractionDigits: 1 });
const lines = Object.entries(sums).sort().map(([metric, s]) => {
  const pct = s.prev ? ((s.now - s.prev) / s.prev) * 100 : null;
  const arrow = pct === null ? '–' : pct >= 0 ? `▲ ${pct.toFixed(1)}%` : `▼ ${Math.abs(pct).toFixed(1)}%`;
  const colour = pct === null ? '#666' : pct >= 0 ? '#0a7d32' : '#b3261e';
  return `<tr><td>${metric}</td><td align="right">${fmt(s.now)}</td><td align="right">${fmt(s.prev)}</td>
          <td align="right" style="color:${colour}">${arrow}</td></tr>`;
}).join('');
const title = $('⚙️ Config').first().json.reportTitle;
const html = `<h2 style="font-family:sans-serif">${title}</h2>
  <p style="font-family:sans-serif">Week ending ${today.minus({ days: 1 }).toFormat('d LLL yyyy')}</p>
  <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
  <tr style="background:#2c0a94;color:#fff"><th>Metric</th><th>This week</th><th>Last week</th><th>Change</th></tr>
  ${lines || '<tr><td colspan="4">No data for this period</td></tr>'}</table>`;
return [{ json: { subject: `${title}: week ending ${today.minus({ days: 1 }).toFormat('d LLL')}`, html } }];
